<?php
/** Health, safe mode and reversible repair. */
defined( 'ABSPATH' ) || exit;
final class VWLB_Diagnostics {
	public static function public_health(){return array('module'=>'File 10','status'=>get_option('vwlb_safe_mode')?'degraded':'ok','version'=>VWLB_VERSION,'schema'=>get_option('vwlb_schema_version','missing'),'providers'=>array_map(function($p){return array('id'=>$p->id(),'capabilities'=>$p->capabilities());},VWLB_Providers::all()));}
	public static function full(){global $wpdb;$tables=array();foreach(array('channels','playlists','media_assets','processing_jobs','videos','captions','live_events','stream_credentials','playback_sessions','moderation','takedowns','audit','outbox','webhooks') as $name){$table=VWLB_Helpers::table($name);$exists=$wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$table));$tables[$name]=array('exists'=>(bool)$exists,'rows'=>$exists?(int)$wpdb->get_var("SELECT COUNT(*) FROM $table"):null);}$dead=$tables['processing_jobs']['exists']?(int)$wpdb->get_var("SELECT COUNT(*) FROM ".VWLB_Helpers::table('processing_jobs')." WHERE status='dead'"):0;$outbox_dead=$tables['outbox']['exists']?(int)$wpdb->get_var("SELECT COUNT(*) FROM ".VWLB_Helpers::table('outbox')." WHERE status='dead'"):0;return array_merge(self::public_health(),array('environment'=>array('wordpress'=>get_bloginfo('version'),'php'=>PHP_VERSION,'multisite'=>is_multisite(),'timezone'=>wp_timezone_string()),'tables'=>$tables,'queues'=>array('processing_dead'=>$dead,'outbox_dead'=>$outbox_dead),'cron'=>array('jobs'=>wp_next_scheduled('vwlb_process_jobs'),'outbox'=>wp_next_scheduled('vwlb_publish_outbox'),'reconcile'=>wp_next_scheduled('vwlb_reconcile_states')),'dependencies'=>apply_filters('vwlb_dependency_health',array()),'requirements'=>VWLB_Contracts::REQUIREMENTS));}
	public static function repair($data){if(!VWLB_Security::can(VWLB_Contracts::CAP_DIAGNOSTICS,null,'repair'))return VWLB_Helpers::error('vwlb_forbidden',__('You cannot run repairs.',VWLB_TEXT_DOMAIN),403);$action=VWLB_Helpers::enum($data['action']??'',array('install_schema','reschedule_cron','retry_dead_jobs','retry_dead_outbox','enable_safe_mode','disable_safe_mode','recount_interactions'),'');if(!$action)return VWLB_Helpers::error('vwlb_repair_invalid',__('Unknown repair action.',VWLB_TEXT_DOMAIN));VWLB_DB::snapshot('repair_before',self::full());global $wpdb;switch($action){case'install_schema':VWLB_DB::install_schema();break;case'reschedule_cron':VWLB_Activator::schedules();break;case'retry_dead_jobs':$wpdb->query("UPDATE ".VWLB_Helpers::table('processing_jobs')." SET status='retry',available_at=UTC_TIMESTAMP(),locked_at=NULL,locked_by=NULL WHERE status='dead'");break;case'retry_dead_outbox':$wpdb->query("UPDATE ".VWLB_Helpers::table('outbox')." SET status='retry',available_at=UTC_TIMESTAMP(),locked_at=NULL WHERE status='dead'");break;case'enable_safe_mode':update_option('vwlb_safe_mode',1,false);break;case'disable_safe_mode':update_option('vwlb_safe_mode',0,false);break;case'recount_interactions':$videos=$wpdb->get_col('SELECT id FROM '.VWLB_Helpers::table('videos'));foreach($videos as $id){foreach(array('like','dislike') as $type){$count=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.VWLB_Helpers::table('interactions').' WHERE video_id=%d AND interaction=%s',$id,$type));$wpdb->update(VWLB_Helpers::table('videos'),array($type.'_count'=>$count),array('id'=>$id));}}break;}VWLB_Helpers::audit('system',0,'repair','','',$action);return array('action'=>$action,'completed'=>true,'health'=>self::full());}
}
